class State:
    behavior: Label
    aware: bool

def flip(x: State) -> State:
    return State(x.behavior, not x.aware)

def functional_distance(x: State, y: State) -> float:
    return dist(x.behavior, y.behavior)

def main() -> None:
    x = State((3.0, 4.0), True)
    z = flip(x)
    assert flip(z) == x
    assert functional_distance(x, z) == 0.0
    print(x, z, functional_distance(x, z))

if __name__ == "__main__":
    main()

from typing import Dict, Hashable, Iterable, Optional, Tuple, TypeVar

K = TypeVar("K", bound=Hashable)

def conflict(rows: Iterable[Tuple[K, bool]]) -> Optional[Tuple[K, bool, bool]]:
    seen: Dict[K, bool] = {}
    for profile, value in rows:
        if profile in seen and seen[profile] != value:
            return profile, seen[profile], value
        seen.setdefault(profile, value)
    return None

def main() -> None:
    reconstructible = [("A", True), ("A", True), ("B", False)]
    obstructed = [("A", True), ("B", False), ("A", False)]
    print("reconstructible conflict:", conflict(reconstructible))
    print("obstruction certificate:", conflict(obstructed))

if __name__ == "__main__":
    main()

