    return True, None

from dataclasses import dataclass
from typing import Generic, TypeVar

B = TypeVar("B")

@dataclass(frozen=True)
class ExperientialGap(Generic[B]):
    label: B

@dataclass(frozen=True)
class IndexedGap(Generic[B]):
    label: B
    index: int
    sentence: str

def experiential_to_indexed(gap: ExperientialGap[B], index: int) -> IndexedGap[B]:
    return IndexedGap(gap.label, index, f"C_{index}")

